def flatten(d: dict) -> dict:
    """Flatten a nested dictionary by joining keys with dots."""
    result = {}

    for key, value in d.items():
        if isinstance(value, dict):
            # Recursively flatten the inner dict
            flattened_value = flatten(value)

            # Join the current key and all subkeys from the recursive call
            joined_key = ".".join(key.split("."))
            result[joined_key] = flattened_value
        else:
            # Non-dict value stays as is (no dot joining needed for this level)
            result[key] = value

    return result
