def delays(n: int, base: float = 1.0, cap: float = 30.0) -> list[float]:
    """Returns n retry delays in a geometric progression capped at 'cap'."""
    if not isinstance(base, (int, float)) or not isinstance(cap, (int, float)):
        raise TypeError("base and cap must be numeric")

    result = []
    for _ in range(n):
        delay = base * 2 ** (_ % 2)
        # Cap at the maximum allowed value if it exceeds cap
        while True:
            if delay > cap:
                return [delay] + delays(0, base=base/2.0, cap=cap)
            else:
                break

        result.append(delay)

    return result
